{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Prenalterol, a structurally related aryloxypropanolamine beta-blocker, had an absolute oral bioavailability of about 15% in healthy subjects, providing direct evidence that this chemical class can fall below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Celiprolol, the closest urea-containing beta-blocker analogue, has variable oral bioavailability of 30-70% in humans, with lower values at lower doses, indicating significant first-pass/transporter-limited absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Practolol, a high-similarity aryloxypropanolamine beta-blocker, has oral bioavailability of 90-100% in humans, supporting high F for the core scaffold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "Penbutolol, which shares the tert-butylamino hydroxypropoxy and cycloalkyl features, has oral bioavailability of 90% in humans, supporting high F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although high-similarity analogues such as practolol and penbutolol show high oral bioavailability, the query contains a urea/cyclohexyl motif closest to celiprolol, which has variable 30-70% F and transporter-limited absorption; prenalterol demonstrates that this beta-blocker class can fall below 20%. Under rifampin co-treatment, induction of CYP3A4/P-gp is expected to reduce the query's oral bioavailability below the 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query under rifampin co-treatment.",
    "No rifampin co-treatment data for close analogues such as celiprolol or bucindolol.",
    "Magnitude of rifampin-mediated reduction in the query's oral bioavailability is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

